CREATE DEFINER=`centadmin`@`localhost` PROCEDURE `currentMinistries`()
BEGIN
    SELECT DISTINCT
        mgt.min_grp_type_desc,
        mc.min_comm_name,
        c.first_name,
        c.last_name,
        r.role_desc
    FROM ministry_committee mc
        JOIN min_group_type mgt ON mgt.min_grp_type_id = mc.min_comm_type_id
        JOIN member_alliance ma ON ma.min_comm_id = mc.min_comm_id
        JOIN roles r            ON r.role_id = ma.role_id
        JOIN contacts c         ON c.contact_id = ma.contact_id
    ORDER BY 
        mgt.min_grp_type_desc,
        mc.min_comm_name,
        c.last_name,
        c.first_name,
        r.role_desc;
END ;;
DELIMITER ;
