CREATE DEFINER=`centadmin`@`localhost` PROCEDURE `eventFinancials`( 
	IN p_event_id INT
)
BEGIN
	SELECT 
		bi.prg_evnt_id, 
		bi.budget_item_id, 
		bi.item_type, 
		bi.item_description, 
		bi.amount AS budget_amount, 
		ba.entry_type, 
		ba.description AS actual_description, 
		ba.amount AS actual_amount
	FROM prg_evnt_budget_items bi
	LEFT JOIN prg_evnt_budget_actuals ba 
		ON ba.prg_evnt_id = bi.prg_evnt_id 
		AND ba.budget_item_id = bi.budget_item_id
	WHERE bi.prg_evnt_id = p_event_id
	ORDER BY bi.item_description;
END ;;
DELIMITER ;
