/*!50003 DROP PROCEDURE IF EXISTS `GetWeeklyCelebrations` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`centadmin`@`localhost` PROCEDURE `GetWeeklyCelebrations`(
    IN in_week_start DATE
)
BEGIN
    -- Derive Sunday start date and Saturday end date
    DECLARE v_start DATE;
    DECLARE v_end DATE;
    
    SET v_start = in_week_start;
    SET v_end = DATE_ADD(in_week_start, INTERVAL 6 DAY);

    SELECT * FROM (
        -- -------------------------------------------------------------
        -- 1. INDIVIDUAL BIRTHDAYS
        -- -------------------------------------------------------------
        SELECT 
            'Birthday' AS celebration_type,
            CONCAT(first_name, ' ', last_name) AS title,
            DATE_FORMAT(date_of_birth, '%M %e') AS display_date,
            CASE 
                WHEN STR_TO_DATE(CONCAT(YEAR(v_start), '-', DATE_FORMAT(date_of_birth, '%m-%d')), '%Y-%m-%d') >= v_start 
                THEN STR_TO_DATE(CONCAT(YEAR(v_start), '-', DATE_FORMAT(date_of_birth, '%m-%d')), '%Y-%m-%d')
                ELSE STR_TO_DATE(CONCAT(YEAR(v_end), '-', DATE_FORMAT(date_of_birth, '%m-%d')), '%Y-%m-%d')
            END AS occurrence_date
        FROM contacts
        WHERE 
            date_of_birth IS NOT NULL 
            AND CAST(date_of_birth AS CHAR) NOT LIKE '0000%'
            AND (is_deceased = 0 OR is_deceased IS NULL)
            AND (
                STR_TO_DATE(CONCAT(YEAR(v_start), '-', DATE_FORMAT(date_of_birth, '%m-%d')), '%Y-%m-%d') BETWEEN v_start AND v_end
                OR STR_TO_DATE(CONCAT(YEAR(v_end), '-', DATE_FORMAT(date_of_birth, '%m-%d')), '%Y-%m-%d') BETWEEN v_start AND v_end
            )

        UNION ALL

        -- -------------------------------------------------------------
        -- 2. COUPLE ANNIVERSARIES
        -- -------------------------------------------------------------
        SELECT DISTINCT
            'Anniversary' AS celebration_type,
            CONCAT(hd.first_name, ' & ', sp.first_name, ' ', hd.last_name) AS title,
            DATE_FORMAT(hd.anniv_date, '%M %e') AS display_date,
            CASE 
                WHEN STR_TO_DATE(CONCAT(YEAR(v_start), '-', DATE_FORMAT(hd.anniv_date, '%m-%d')), '%Y-%m-%d') >= v_start 
                THEN STR_TO_DATE(CONCAT(YEAR(v_start), '-', DATE_FORMAT(hd.anniv_date, '%m-%d')), '%Y-%m-%d')
                ELSE STR_TO_DATE(CONCAT(YEAR(v_end), '-', DATE_FORMAT(hd.anniv_date, '%m-%d')), '%Y-%m-%d')
            END AS occurrence_date
        FROM nbbtm_central.Families f
        JOIN nbbtm_central.contacts hd 
            ON hd.family_id = f.family_id 
           AND hd.contact_id = f.family_id
           AND hd.is_head = 1
        JOIN nbbtm_central.contacts sp 
            ON sp.family_id = f.family_id 
           AND sp.contact_id <> f.family_id
           AND sp.anniv_date = hd.anniv_date
           AND sp.is_head = 0
        WHERE 
            hd.anniv_date IS NOT NULL
            AND CAST(hd.anniv_date AS CHAR) NOT LIKE '0000%'
            AND (hd.is_deceased = 0 OR hd.is_deceased IS NULL)
            AND (sp.is_deceased = 0 OR sp.is_deceased IS NULL)
            AND (
                STR_TO_DATE(CONCAT(YEAR(v_start), '-', DATE_FORMAT(hd.anniv_date, '%m-%d')), '%Y-%m-%d') BETWEEN v_start AND v_end
                OR STR_TO_DATE(CONCAT(YEAR(v_end), '-', DATE_FORMAT(hd.anniv_date, '%m-%d')), '%Y-%m-%d') BETWEEN v_start AND v_end
            )
    ) AS celebrations
    -- Sort by type first ('Birthday' before 'Anniversary'), then by date ASC
    ORDER BY 
        CASE WHEN celebration_type = 'Birthday' THEN 1 ELSE 2 END ASC,
        occurrence_date ASC;
END ;;
DELIMITER ;
