/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`admincentral`@`%` PROCEDURE `get_calendar`(
    IN p_start_month DATE,
    IN p_month_count INT
)
BEGIN
    DECLARE v_start_date DATE;
    DECLARE v_end_date DATE;

    IF p_start_month IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'A starting month is required';
    END IF;

    IF p_month_count IS NULL OR p_month_count < 1 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Month count must be at least 1';
    END IF;

    -- Normalize the supplied date to the first day of its month.
    SET v_start_date =
        STR_TO_DATE(DATE_FORMAT(p_start_month, '%Y-%m-01'), '%Y-%m-%d');

    -- Exclusive end date.
    SET v_end_date = DATE_ADD(v_start_date, INTERVAL p_month_count MONTH);

    WITH RECURSIVE calendar_dates AS (
        SELECT v_start_date AS date_val

        UNION ALL

        SELECT DATE_ADD(date_val, INTERVAL 1 DAY)
        FROM calendar_dates
        WHERE date_val < DATE_SUB(v_end_date, INTERVAL 1 DAY)
    )
    SELECT
        d.date_val,
        DAY(d.date_val) AS day_num,
        DAYOFWEEK(d.date_val) AS day_of_week,
        YEARWEEK(d.date_val, 0) AS year_week,
        DATE_FORMAT(d.date_val, '%Y-%m') AS calendar_month,
        e.prg_evnt_id,
        pe.prg_evnt_name AS event_title,
        DATE_FORMAT(e.start_datetime, '%m/%e/%Y') AS event_date,
        DATE_FORMAT(e.start_datetime, '%h:%i %p') AS event_time
    FROM calendar_dates AS d
    LEFT JOIN prg_evnt_schedules AS e
        ON e.start_datetime >= d.date_val
       AND e.start_datetime < DATE_ADD(d.date_val, INTERVAL 1 DAY)
    LEFT JOIN programs_events AS pe
        ON pe.prg_evnt_id = e.prg_evnt_id
    ORDER BY
        d.date_val,
        e.start_datetime,
        e.prg_evnt_id;
END ;;
DELIMITER ;
