/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`admincentral`@`%` PROCEDURE `get_contact_birthdays`(
    IN p_months_json JSON
)
BEGIN
    WITH RECURSIVE
    selected_months_raw AS (
        SELECT
            selected.month_number,
            selected.selection_order
        FROM JSON_TABLE(
            CAST(
                COALESCE(
                    NULLIF(TRIM(p_months_json), ''),
                    '[]'
                ) AS JSON
            ),
            '$[*]' COLUMNS (
                selection_order FOR ORDINALITY,
                month_number INT PATH '$'
            )
        ) AS selected
        WHERE selected.month_number BETWEEN 1 AND 12
    ),
    selected_months AS (
        SELECT
            month_number,
            MIN(selection_order) AS sort_order
        FROM selected_months_raw
        GROUP BY month_number
    ),
    month_offsets AS (
        SELECT 0 AS month_offset

        UNION ALL

        SELECT month_offset + 1
        FROM month_offsets
        WHERE month_offset < 11
    ),
    months_to_report AS (
        /* Use selected months in the order supplied. */
        SELECT
            month_number,
            sort_order
        FROM selected_months

        UNION ALL

        /* Default: 12 months beginning with the current month. */
        SELECT
            MOD(
                MONTH(CURRENT_DATE) - 1 + month_offset,
                12
            ) + 1 AS month_number,
            month_offset + 1 AS sort_order
        FROM month_offsets
        WHERE NOT EXISTS (
            SELECT 1
            FROM selected_months
        )
    )
    SELECT
        c.contact_id,
        c.first_name,
        c.last_name,
        c.n_sufix,
        c.date_of_birth
    FROM contacts AS c
    JOIN months_to_report AS m
        ON m.month_number = MONTH(c.date_of_birth)
    WHERE c.date_of_birth IS NOT NULL
    ORDER BY
        m.sort_order,
        DAY(c.date_of_birth),
        c.last_name,
        c.first_name;
END ;;
DELIMITER ;
