CREATE DEFINER=`centadmin`@`localhost` PROCEDURE `printContacts`(
 p_is_active TINYINT,
 p_is_member TINYINT,
 sel_opt ENUM('Y','A','E')
)
BEGIN
SET @is_active = p_is_active;
 SET @is_member = p_is_member;
 
 SET @sql = 'SELECT c.contact_id, t.titleabr, COALESCE(c.last_name, '''') AS last_name, COALESCE(c.first_name, '''') AS first_name, c.gender, c.phone_1, c.c_email
 FROM contacts c
	JOIN title t on t.title_id = c.title_id
 WHERE c.is_active = ? AND c.is_member = ?';

 IF sel_opt = 'Y' THEN
SET @sql = CONCAT(@sql, ' AND c.is_child = 1');
 ELSEIF sel_opt = 'A' THEN
SET @sql = CONCAT(@sql, ' AND c.is_child = 0');
 END IF;

 SET @sql = CONCAT(@sql, ' ORDER BY c.last_name, c.first_name ASC');

 PREPARE stmt FROM @sql;
 EXECUTE stmt USING @is_active, @is_member;
 DEALLOCATE PREPARE stmt;
END ;;
DELIMITER ;
